// App.js
import React, { useState } from 'react';
import { Grommet, Box, FormField, RangeInput } from 'grommet';

const theme = {
  global: {
    font: { family: 'Arial', size: '14px', height: '20px' },
  },
  formField: {
    border: {
      position: 'inner',
      side: 'all',
      color: 'light-4',
      radius: '6px',
    },
    content: {
      pad: 'small',
    },
    label: {
      margin: { bottom: 'small', left: 'small' },
    },
  },
};

export const App = () => {
  const [value, setValue] = useState(50);
  return (
    <Grommet theme={theme} full>
      <Box fill align="center" justify="center" pad="large">
        <FormField label="Age" name="age">
          <RangeInput
            name="age"
            min={0}
            max={100}
            value={value}
            onChange={event => setValue(event.target.value)}
          />
        </FormField>
      </Box>
    </Grommet>
  );
};

